-- Generated by tools/GenerateRptViews.py; edit the generator, not this file.
-- Accounts payable aging: one row per approved bill or expense report with a balance, bucketed by days past due as of today in the company's time zone. Needs ap.view.
CREATE VIEW rpt.ApAging
AS
SELECT
    b.Id AS BillId,
    b.BillNumber AS BillNumber,
    CONVERT(BIT, IIF(b.PayeeUserId IS NULL, 0, 1)) AS IsExpenseReport,
    COALESCE(v.Name, u.DisplayName) AS PayeeName,
    b.BillDate AS BillDate,
    b.DueDate AS DueDate,
    b.Total AS Total,
    b.BalanceDue AS BalanceDue,
    d.Days AS DaysPastDue,
    CASE WHEN d.Days = 0 THEN N'Current' WHEN d.Days <= 30 THEN N'1-30' WHEN d.Days <= 60 THEN N'31-60' WHEN d.Days <= 90 THEN N'61-90' ELSE N'Over 90' END AS AgingBucket,
    CASE WHEN d.Days = 0 THEN 0 WHEN d.Days <= 30 THEN 1 WHEN d.Days <= 60 THEN 2 WHEN d.Days <= 90 THEN 3 ELSE 4 END AS AgingBucketOrder
FROM ap.Bill AS b
JOIN lkp.BillStatus AS s ON s.TenantId = b.TenantId AND s.Id = b.BillStatusId
JOIN admin.Tenant AS tn ON tn.Id = b.TenantId
LEFT JOIN ap.Vendor AS v ON v.TenantId = b.TenantId AND v.Id = b.VendorId
LEFT JOIN sec.AppUser AS u ON u.TenantId = b.TenantId AND u.Id = b.PayeeUserId
CROSS APPLY (SELECT IIF(b.DueDate < CAST(SYSUTCDATETIME() AT TIME ZONE 'UTC' AT TIME ZONE tn.TimeZoneId AS DATE), DATEDIFF(DAY, b.DueDate, CAST(SYSUTCDATETIME() AT TIME ZONE 'UTC' AT TIME ZONE tn.TimeZoneId AS DATE)), 0) AS Days) AS d
WHERE (s.SystemCode = 'OPEN' OR s.SystemCode = 'PARTIAL') AND b.BalanceDue > 0 AND EXISTS (SELECT 1 FROM sec.fn_UserHasPermission(b.TenantId, CONVERT(INT, SESSION_CONTEXT(N'UserId')), 'ap.view'));
GO
